1	/* ============================ Người treo dù: trang bị bằng code ============================
2	   Một BufferGeometry có xương (skinIndex / skinWeight) cho SkinnedMesh: ghế ngồi + hai má ghế, hộp dù dự phòng dưới ghế + quai kéo đỏ, ba lô / tấm bảo vệ lưng,
3	   đệm thắt lưng, đai vai (lưng → vai → ngực → carabiner), đai ngực có khóa, vòng đai đùi có khóa, carabiner (vòng bầu dục), riser (đai dẹt hai nhánh),
4	   quai phanh (thanh trong nắm tay), dây phanh, dây treo.
5	   Mỗi đỉnh gắn cứng một xương (trọng số 1). Đai và dây nối hai xương là dải có đầu này một xương, đầu kia một xương nên luôn bám người lẫn dù khi xương dịch chuyển.
6	   Hệ tọa độ: hệ group dù (+X bay, +Y lên, +Z phải); mọi bộ phận dựng theo vị trí nghỉ của xương truyền vào (PlGearRest, rig.ts đo ở tư thế bay nền), không có số tuyệt đối.
7	   Khối đệm là siêu elip (bo tròn, pháp tuyến mượt); đặt trong "hệ thân": trục a dọc thân (hông → Spine2), b ra trước vuông góc a, c = +Z.
8	   Thuần BufferGeometry, không cần DOM nên test node dùng được. Thông số: CONFIG.explore.pilot.gear. Trần 6 000 tam giác (test kiểm). */
9	import * as THREE from 'three';
10	import { CONFIG } from '../../config';
11	import { exLineTops, exBrakeTops } from '../glider';
12	
13	/* Thứ tự xương = giá trị skinIndex. 'wing' là gốc cánh (đầu trên của dây), 'hang' là đỉnh riser (tâm lắc), 'pack' là ba lô lệch pha với thân */
14	export const PL_GEAR_BONES = ['wing', 'hang', 'pelvis', 'spine', 'handL', 'handR', 'thighL', 'thighR', 'pack'] as const;
15	/* Đoạn đỉnh của một dây trong geometry: kind 'line' (dây treo) hoặc 'brake' (dây phanh chính quai → điểm tụ); ba / bb = xương hai đầu; geometry.userData.spans */
16	export interface PlGearSpan { kind: 'line' | 'brake'; ba: number; bb: number; start: number; count: number }
17	export interface PlGearRest {
18	  hang: number[]; pelvis: number[]; spine: number[]; handL: number[]; handR: number[]; thighL: number[]; thighR: number[];   // vị trí nghỉ trong hệ group dù, m (hang: giữa hai carabiner; spine: Spine2)
19	  kneeL?: number[]; kneeR?: number[];   // m — gối (đầu xương cẳng chân); thiếu thì đùi + 0,4 m về trước
20	  gripL?: number[]; gripR?: number[];   // m — điểm nắm quai phanh (giữa nắm tay); thiếu thì lấy vị trí xương bàn tay
21	  barL?: number[]; barR?: number[];     // hướng đơn vị của thanh quai phanh (ngang lòng bàn tay); thiếu thì +Z
22	  fingL?: number[]; fingR?: number[];   // hướng đơn vị từ cổ tay ra ngón; thiếu thì +Y
23	}
24	
25	const PG = CONFIG.explore.pilot, GC = PG.gear;
26	const BI = (n: typeof PL_GEAR_BONES[number]): number => PL_GEAR_BONES.indexOf(n);
27	const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
28	const VA = (a: number[]) => new THREE.Vector3(a[0], a[1], a[2]);
29	const COL = (hex: string): number[] => { const c = new THREE.Color(hex); return [c.r, c.g, c.b]; };
30	const spow = (v: number, e: number): number => Math.sign(v) * Math.pow(Math.abs(v), e);
31	
32	/* Bộ gom đỉnh không chỉ số: mỗi tam giác có màu và xương theo đỉnh; pháp tuyến phẳng hoặc truyền vào */
33	class GearBuf {
34	  pos: number[] = []; nor: number[] = []; col: number[] = []; si: number[] = [];
35	  spans: PlGearSpan[] = [];   // đoạn đỉnh của từng dây (test dùng để kiểm hai đầu hai xương)
36	  span(kind: PlGearSpan['kind'], ba: number, bb: number, f: () => void): void {
37	    const start = this.si.length; f(); this.spans.push({ kind, ba, bb, start, count: this.si.length - start });
38	  }
39	  /* Một tam giác; ba xương theo ba đỉnh; ns: pháp tuyến từng đỉnh (bỏ trống = phẳng) */
40	  tri(a: THREE.Vector3, b: THREE.Vector3, c: THREE.Vector3, ba: number, bb: number, bc: number, rgb: number[], ns?: THREE.Vector3[]): void {
41	    const n = b.clone().sub(a).cross(c.clone().sub(a));
42	    if (n.lengthSq() < 1e-14) return;
43	    n.normalize();
44	    const pts: [THREE.Vector3, number][] = [[a, ba], [b, bb], [c, bc]];
45	    for (let i = 0; i < 3; i++) {
46	      const [p, bone] = pts[i], nn = ns ? ns[i] : n;
47	      this.pos.push(p.x, p.y, p.z); this.nor.push(nn.x, nn.y, nn.z); this.col.push(rgb[0], rgb[1], rgb[2]); this.si.push(bone);
48	    }
49	  }
50	  /* Mặt bốn đỉnh; ref nằm bên trong khối, mặt luôn quay ra xa ref */
51	  quad(p: THREE.Vector3[], bn: number[], rgb: number[], ref: THREE.Vector3): void {
52	    const ctr = p[0].clone().add(p[1]).add(p[2]).add(p[3]).multiplyScalar(0.25);
53	    const n = p[1].clone().sub(p[0]).cross(p[2].clone().sub(p[0]));
54	    const o = n.dot(ctr.sub(ref)) < 0 ? [0, 3, 2, 1] : [0, 1, 2, 3];
55	    this.tri(p[o[0]], p[o[1]], p[o[2]], bn[o[0]], bn[o[1]], bn[o[2]], rgb);
56	    this.tri(p[o[0]], p[o[2]], p[o[3]], bn[o[0]], bn[o[2]], bn[o[3]], rgb);
57	  }
58	  /* Khối đệm siêu elip: tâm c, ba trục đơn vị ax, nửa kích thước h, độ vuông e, chia nu (vĩ) × nv (kinh), một xương */
59	  blob(c: THREE.Vector3, ax: THREE.Vector3[], h: number[], e: number, nu: number, nv: number, bone: number, rgb: number[]): void {
60	    const P: THREE.Vector3[][] = [], N: THREE.Vector3[][] = [];
61	    for (let i = 0; i <= nu; i++) {
62	      const u = -Math.PI / 2 + Math.PI * i / nu, rp: THREE.Vector3[] = [], rn: THREE.Vector3[] = [];
63	      for (let j = 0; j <= nv; j++) {
64	        const v = -Math.PI + 2 * Math.PI * j / nv;
65	        const l = [h[0] * spow(Math.cos(u), e) * spow(Math.cos(v), e), h[1] * spow(Math.cos(u), e) * spow(Math.sin(v), e), h[2] * spow(Math.sin(u), e)];
66	        const n = [spow(Math.cos(u), 2 - e) * spow(Math.cos(v), 2 - e) / h[0], spow(Math.cos(u), 2 - e) * spow(Math.sin(v), 2 - e) / h[1], spow(Math.sin(u), 2 - e) / h[2]];
67	        rp.push(c.clone().addScaledVector(ax[0], l[0]).addScaledVector(ax[1], l[1]).addScaledVector(ax[2], l[2]));
68	        const nn = V(0, 0, 0).addScaledVector(ax[0], n[0]).addScaledVector(ax[1], n[1]).addScaledVector(ax[2], n[2]);
69	        rn.push(nn.lengthSq() > 1e-12 ? nn.normalize() : ax[2].clone().multiplyScalar(Math.sign(l[2]) || 1));
70	      }
71	      P.push(rp); N.push(rn);
72	    }
73	    for (let i = 0; i < nu; i++) for (let j = 0; j < nv; j++) {
74	      const q = [[i, j], [i + 1, j], [i + 1, j + 1], [i, j + 1]];
75	      const g = (k: number) => P[q[k][0]][q[k][1]], gn = (k: number) => N[q[k][0]][q[k][1]];
76	      /* chiều quay mặt theo pháp tuyến giải tích (mặt suy biến ở cực bị tri() bỏ) */
77	      const flip = g(1).clone().sub(g(0)).cross(g(2).clone().sub(g(0))).dot(gn(0).clone().add(gn(2))) < 0
78	        || (g(1).distanceToSquared(g(0)) < 1e-12 && g(2).clone().sub(g(0)).cross(g(3).clone().sub(g(0))).dot(gn(0).clone().add(gn(2))) < 0);
79	      const ts = flip ? [[0, 2, 1], [0, 3, 2]] : [[0, 1, 2], [0, 2, 3]];
80	      for (const t of ts) this.tri(g(t[0]), g(t[1]), g(t[2]), bone, bone, bone, rgb, [gn(t[0]), gn(t[1]), gn(t[2])]);
81	    }
82	  }
83	  /* Dải đai dẹt qua các điểm pts: bề rộng w nằm ngang, bề dày t theo outs (pháp tuyến bề mặt tại từng điểm); bones từng điểm; closed: khép vòng */
84	  band(pts: THREE.Vector3[], outs: THREE.Vector3[], bones: number[], w: number, t: number, rgb: number[], closed = false): void {
85	    const n = pts.length, rings: THREE.Vector3[][] = [];
86	    for (let i = 0; i < n; i++) {
87	      const prev = pts[closed ? (i - 1 + n) % n : Math.max(0, i - 1)], next = pts[closed ? (i + 1) % n : Math.min(n - 1, i + 1)];
88	      const tg = next.clone().sub(prev).normalize(), o = outs[i].clone().addScaledVector(tg, -outs[i].dot(tg));
89	      if (o.lengthSq() < 1e-8) o.copy(Math.abs(tg.y) < 0.9 ? V(0, 1, 0) : V(1, 0, 0)).addScaledVector(tg, -o.dot(tg));
90	      o.normalize();
91	      const sd = tg.clone().cross(o).normalize(), p = pts[i];
92	      rings.push([[1, 1], [-1, 1], [-1, -1], [1, -1]].map(([s, r]) => p.clone().addScaledVector(sd, s * w / 2).addScaledVector(o, r * t / 2)));
93	    }
94	    const segs = closed ? n : n - 1;
95	    for (let i = 0; i < segs; i++) {
96	      const j = (i + 1) % n, ra = rings[i], rb = rings[j], ref = pts[i].clone().add(pts[j]).multiplyScalar(0.5);
97	      for (let k = 0; k < 4; k++) this.quad([ra[k], ra[(k + 1) % 4], rb[(k + 1) % 4], rb[k]], [bones[i], bones[i], bones[j], bones[j]], rgb, ref);
98	    }
99	  }
100	  /* Lăng trụ bốn cạnh từ a tới b (dây): mặt cắt w × t; đáy a xương ba, đáy b xương bb */
101	  prism(a: THREE.Vector3, b: THREE.Vector3, ba: number, bb: number, rgb: number[], w: number, t: number, hint = V(0, 0, 1)): void {
102	    const d = b.clone().sub(a);
103	    if (d.length() < 1e-4) return;
104	    d.normalize();
105	    let u = hint.clone().sub(d.clone().multiplyScalar(hint.dot(d)));
106	    if (u.lengthSq() < 1e-6) u = Math.abs(d.y) < 0.9 ? V(0, 1, 0).sub(d.clone().multiplyScalar(d.y)) : V(1, 0, 0).sub(d.clone().multiplyScalar(d.x));
107	    u.normalize();
108	    const v = d.clone().cross(u).normalize();
109	    const ring = (o: THREE.Vector3) => [[1, 1], [-1, 1], [-1, -1], [1, -1]].map(([s, r]) => o.clone().addScaledVector(u, s * w / 2).addScaledVector(v, r * t / 2));
110	    const ra = ring(a), rb = ring(b), ref = a.clone().add(b).multiplyScalar(0.5);
111	    for (let k = 0; k < 4; k++) this.quad([ra[k], ra[(k + 1) % 4], rb[(k + 1) % 4], rb[k]], [ba, ba, bb, bb], rgb, ref);
112	  }
113	  /* Vòng bầu dục (carabiner) tâm c, mặt phẳng vuông góc nAx, trục dài lAx: nửa trục r1 (dọc lAx), r2; thanh vuông bề dày t, k đoạn */
114	  ring(c: THREE.Vector3, nAx: THREE.Vector3, lAx: THREE.Vector3, r1: number, r2: number, t: number, k: number, bone: number, rgb: number[]): void {
115	    const s = nAx.clone().cross(lAx).normalize(), pts: THREE.Vector3[] = [], outs: THREE.Vector3[] = [];
116	    for (let i = 0; i < k; i++) { const a = 2 * Math.PI * i / k; pts.push(c.clone().addScaledVector(lAx, r1 * Math.cos(a)).addScaledVector(s, r2 * Math.sin(a))); outs.push(nAx.clone()); }
117	    this.band(pts, outs, pts.map(() => bone), t, t, rgb, true);
118	  }
119	  geometry(): THREE.BufferGeometry {
120	    const g = new THREE.BufferGeometry(), n = this.si.length;
121	    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
122	    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nor, 3));
123	    g.setAttribute('color', new THREE.Float32BufferAttribute(this.col, 3));
124	    const idx = new Uint16Array(n * 4), wt = new Float32Array(n * 4);
125	    for (let i = 0; i < n; i++) { idx[i * 4] = this.si[i]; wt[i * 4] = 1; }
126	    g.setAttribute('skinIndex', new THREE.Uint16BufferAttribute(idx, 4));
127	    g.setAttribute('skinWeight', new THREE.Float32BufferAttribute(wt, 4));
128	    g.userData.spans = this.spans;
129	    return g;
130	  }
131	}
132	
133	/* Dựng toàn bộ trang bị quanh các vị trí nghỉ của xương */
134	export function plGearGeometry(rest: PlGearRest): THREE.BufferGeometry {
135	  const b = new GearBuf(), C = GC.colors, E = GC.round;
136	  const harness = COL(C.harness), strap = COL(C.strap), pack = COL(C.pack), toggle = COL(C.toggle), line = COL(C.line), metal = COL(C.metal), red = COL(C.reserve);
137	  const bone = { wing: BI('wing'), hang: BI('hang'), pel: BI('pelvis'), spine: BI('spine'), pack: BI('pack') };
138	  const X = V(1, 0, 0), Y = V(0, 1, 0), Z = V(0, 0, 1);
139	  const Pl = VA(rest.pelvis), S = VA(rest.spine), H = VA(rest.hang);
140	  /* hệ thân: a dọc thân (hông → Spine2), b ra trước vuông góc a trong mặt X-Y, c = +Z; tâm thân lấy z = 0 (đối xứng) */
141	  const ua = S.clone().sub(Pl); ua.z = 0; if (ua.lengthSq() < 1e-6) ua.set(0, 1, 0); ua.normalize();
142	  const fb = V(ua.y, -ua.x, 0);
143	  const T = (a: number, bb: number, c: number) => V(Pl.x, Pl.y, 0).addScaledVector(ua, a).addScaledVector(fb, bb).addScaledVector(Z, c);
144	  const G = (l: number[]) => V(Pl.x + l[0], Pl.y + l[1], l[2]);   // hệ dù so với xương hông (z tuyệt đối)
145	  const rot = (a: number) => [V(Math.cos(a), Math.sin(a), 0), V(-Math.sin(a), Math.cos(a), 0), Z.clone()];
146	
147	  /* Ghế ngồi (nghiêng theo đùi), hai má ghế, hộp dù dự phòng dưới ghế: gắn hông */
148	  const st = GC.seat, sd = GC.side, rv = GC.reserve;
149	  b.blob(G(st.c), rot(st.tilt), st.h, E, 6, 12, bone.pel, harness);
150	  for (const s of [-1, 1]) b.blob(G([sd.c[0], sd.c[1], s * sd.c[2]]), rot(st.tilt), sd.h, E, 5, 10, bone.pel, harness);
151	  const rc = G(rv.c);
152	  b.blob(rc, rot(st.tilt), rv.h, E, 5, 10, bone.pel, pack);
153	  /* quai kéo dù dự phòng: tay nắm đỏ ở mép phải hộp, dải đỏ nối vào hộp */
154	  const hp = V(rc.x + rv.handle[0], rc.y, rv.handle[1]);
155	  b.band([V(rc.x - rv.h[0] * 0.3, rc.y + rv.h[1] * 0.5, rv.h[2] + 0.004), V(hp.x - 0.02, hp.y, rv.h[2] + 0.006), hp], [Z, Z, Z], [bone.pel, bone.pel, bone.pel], 0.025, 0.008, red);
156	  b.blob(hp, [X, Y, Z], rv.handleH, 0.6, 3, 6, bone.pel, red);
157	
158	  /* Đệm thắt lưng (hông) và ba lô / tấm bảo vệ lưng (xương pack, lắc trễ nhẹ) theo hệ thân */
159	  const ax = [ua, fb, Z];
160	  b.blob(T(GC.lumbar.a, GC.lumbar.b, 0), ax, GC.lumbar.h, E, 5, 10, bone.pel, harness);
161	  b.blob(T(GC.back.a, GC.back.b, 0), ax, GC.back.h, E, 8, 14, bone.pack, pack);
162	
163	  /* Đai vai: sau lưng → đỉnh vai → ngực → bụng (Spine2) → carabiner (hông); carabiner, riser, dây treo */
164	  const W = GC.strapW, Tk = GC.strapT, sp = GC.shoulder;
165	  for (const s of [-1, 1]) {
166	    const c = V(H.x, H.y, s * PG.hang.half);
167	    const pts = sp.map((q) => T(q[0], q[1], s * q[2]));
168	    const outs = sp.map((q, i) => (i === 1 ? ua.clone() : fb.clone().multiplyScalar(Math.sign(q[1]) || 1)));
169	    pts.push(c.clone().add(V(-0.01, GC.carab.h * 0.9, 0))); outs.push(X.clone());
170	    b.band(pts, outs, pts.map((_, i) => (i < sp.length - 1 ? bone.spine : bone.pel)), W, Tk, strap);
171	    /* đai hông: từ đáy carabiner vòng ra má ghế */
172	    b.band([c.clone().add(V(-0.01, -GC.carab.h * 0.9, 0)), G([sd.c[0] + 0.04, sd.c[1] + sd.h[1] * 0.6, s * (sd.c[2] + sd.h[2])])], [X, V(0, 0, s)], [bone.pel, bone.pel], W, Tk, strap);
173	    /* carabiner: vòng bầu dục đứng trong mặt phẳng X-Y */
174	    b.ring(c, Z, Y, GC.carab.h, GC.carab.w, GC.carab.bar, 12, bone.pel, metal);
175	    /* riser: hai nhánh đai dẹt (trước / sau) từ đỉnh carabiner lên đỉnh riser (xương hang, tâm lắc) */
176	    const top = V(c.x, c.y + PG.riser, c.z);
177	    for (const dx of [-1, 1]) b.band([c.clone().add(V(dx * 0.008, GC.carab.h * 0.85, 0)), top.clone().add(V(dx * GC.riserSplit, -0.02, 0))], [Z, Z], [bone.pel, bone.hang], 0.022, 0.004, strap);
178	    /* dây treo: lineCount dây từ đỉnh riser lên cánh */
179	    for (const t of exLineTops()) if (t.side === s) b.span('line', bone.hang, bone.wing, () => b.prism(top, V(t.x, t.y, t.z), bone.hang, bone.wing, line, GC.lineR * 2, GC.lineR * 2));
180	  }
181	  /* đai ngực nối hai đai vai + khóa giữa */
182	  const cy = GC.chestY, sc = sp[3][2], chestB = (sp[2][1] + sp[3][1]) / 2 + Tk;
183	  for (const s of [-1, 1]) b.band([T(cy, chestB, s * sc), T(cy, chestB + 0.008, s * 0.03)], [fb, fb], [bone.spine, bone.spine], W * 0.8, Tk, strap);
184	  b.blob(T(cy, chestB + 0.012, 0), [fb, ua, Z], GC.buckle, 0.5, 3, 6, bone.spine, metal);
185	
186	  /* Vòng đai đùi quanh từng đùi (vuông góc trục đùi) + khóa phía trên + đai nối lên má ghế */
187	  for (const s of [-1, 1]) {
188	    const Tg = VA(s < 0 ? rest.thighL : rest.thighR), kr = s < 0 ? rest.kneeL : rest.kneeR, Kn = kr ? VA(kr) : Tg.clone().add(V(0.4, 0, 0));
189	    const bt = BI(s < 0 ? 'thighL' : 'thighR');
190	    const d = Kn.clone().sub(Tg).normalize(), cc = Tg.clone().lerp(Kn, GC.thigh.at);
191	    const e1 = Z.clone().cross(d).normalize(), e2 = d.clone().cross(e1).normalize();   // e1 ≈ lên, e2 ≈ ngang
192	    const pts: THREE.Vector3[] = [], outs: THREE.Vector3[] = [];
193	    for (let i = 0; i < 14; i++) { const a = 2 * Math.PI * i / 14, o = e1.clone().multiplyScalar(Math.cos(a)).addScaledVector(e2, Math.sin(a)); pts.push(cc.clone().addScaledVector(o, GC.thigh.r)); outs.push(o); }
194	    b.band(pts, outs, pts.map(() => bt), W, Tk, strap, true);
195	    b.blob(cc.clone().addScaledVector(e1, GC.thigh.r + GC.buckle[0]), [e1, d, e2], GC.buckle, 0.5, 3, 6, bt, metal);
196	    b.band([cc.clone().addScaledVector(e2, s * GC.thigh.r).addScaledVector(d, -0.02), G([sd.c[0] + sd.h[0] * 0.6, sd.c[1] + sd.h[1] * 0.3, s * (sd.c[2] + sd.h[2])])], [e2.clone().multiplyScalar(s), V(0, 0, s)], [bt, bone.pel], W, Tk, strap);
197	  }
198	
199	  /* Quai phanh ×2 gắn xương bàn tay (thanh ngang lòng bàn tay, trong nắm tay); dây phanh chính từ quai lên điểm tụ (gắn cánh) rồi chia ba nhánh lên mép sau cánh */
200	  for (const s of [-1, 1]) {
201	    const hd = s < 0 ? rest.handL : rest.handR, bh = BI(s < 0 ? 'handL' : 'handR');
202	    const gp = (s < 0 ? rest.gripL : rest.gripR) ?? hd, br = (s < 0 ? rest.barL : rest.barR) ?? [0, 0, 1], fg = (s < 0 ? rest.fingL : rest.fingR) ?? [0, 1, 0];
203	    const c = VA(gp), axb = VA(br).normalize(), fd = VA(fg).normalize();
204	    b.prism(c.clone().addScaledVector(axb, -GC.toggleLen), c.clone().addScaledVector(axb, GC.toggleLen), bh, bh, toggle, GC.toggleW, GC.toggleW, fd);
205	    const tops = exBrakeTops().filter((t) => t.side === s);
206	    const tx = tops.reduce((a, t) => a + t.x, 0) / tops.length, ty = tops.reduce((a, t) => a + t.y, 0) / tops.length, tz = tops.reduce((a, t) => a + t.z, 0) / tops.length;
207	    const join = V(c.x + (tx - c.x) * GC.brakeJoin, c.y + (ty - c.y) * GC.brakeJoin, c.z + (tz - c.z) * GC.brakeJoin);
208	    b.span('brake', bh, bone.wing, () => b.prism(c, join, bh, bone.wing, line, GC.lineR * 1.5, GC.lineR * 1.5));
209	    for (const t of tops) b.prism(join, V(t.x, t.y, t.z), bone.wing, bone.wing, line, GC.lineR * 1.5, GC.lineR * 1.5);
210	  }
211	  return b.geometry();
212	}
213	
214	/* Vật liệu dùng chung: màu theo đỉnh, nhám, không kim loại để cả trang bị vẫn 1 lệnh vẽ. DoubleSide: dải đai mỏng nhìn được cả hai mặt */
215	let plGearMat: THREE.MeshStandardMaterial | null = null;
216	export function plGearMaterial(): THREE.MeshStandardMaterial {
217	  return plGearMat ??= new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.8, metalness: 0.1, side: THREE.DoubleSide });
218	}
