1	/* ===== Người treo dù: điều phối (src/explore/pilot/index.ts) =====
2	   Gắn / cập nhật / gỡ nhân vật có xương dưới mỗi dù (của mình lẫn người khác), spec §4, §7:
3	   - plPreload(): bắt đầu nạp pilot.glb (thẻ Dù lượn, explore.start / startWatching). Trang thường không gọi nên không tải.
4	   - plUpdate(): gọi từ exPlaceGlider mỗi khung. Nguồn chưa về / lỗi → giữ hình 'full' (người khối). Nguồn đã về và dù đang hiện → gắn trong vòng khung:
5	     mesh cánh đổi sang hình 'canopy', thêm nhóm con ex-pilot (rig.ts). Dù đang ẩn lúc nguồn về thì chưa gắn (Review Focus 1).
6	   - Tín hiệu (react.ts plSignals) từ vị trí + bank của chính dù nên dùng chung cho dù của mình, dù người khác, chế độ xem; gió đọc weatherU (cùng nguồn cây / mưa).
7	   - `?pilot=off` ép hình khối; group.userData.plOff = true (remote.ts: dù người khác khi pilot.remote = false hoặc điện thoại) cũng giữ hình khối.
8	   Không cấp phát mỗi khung (trừ lần gắn). */
9	import * as THREE from 'three';
10	import { CONFIG } from '../../config';
11	import { weatherU } from '../../core/shared';
12	import { exGliderGeometry } from '../glider';
13	import type { GliderState } from '../flight';
14	import { plSignals, type PlPose, type PlSignals, type PlTrack } from './react';
15	import { PlRig } from './rig';
16	import { plLoad, plSetWarm as plSetWarmLoad, type PlSource } from './load';
17	
18	interface PlEntry { rig: PlRig | null; track: PlTrack; sig: PlSignals; seed: number }
19	
20	const entries = new Map<THREE.Group, PlEntry>();
21	const OFF = typeof location !== 'undefined' && new URLSearchParams(location.search).get('pilot') === 'off';
22	let loader: () => Promise<PlSource | null> = plLoad;
23	let src: PlSource | null | undefined;   // undefined = chưa có kết quả, null = lỗi (giữ hình khối suốt phiên)
24	let asked = false, gen = 0, seeds = 0;
25	
26	/* Nguồn nếu đã nạp xong; chưa thì bắt đầu nạp (một lần) và trả null. Không ném */
27	function need(): PlSource | null {
28	  if (src !== undefined) return src;
29	  if (!asked) {
30	    asked = true;
31	    const g = gen, done = (r: PlSource | null) => { if (g === gen) src = r || null; };
32	    try { loader().then(done, () => done(null)); } catch { done(null); }
33	  }
34	  return null;
35	}
36	
37	/* Mức gió thời tiết 0..1 cho người treo: gió trung bình + giật (m/s, weather/index.ts ghi vào weatherU) chia windRef */
38	function plWind(): number {
39	  const v = (weatherU.uWind.value + weatherU.uGust.value) / CONFIG.explore.pilot.windRef;
40	  return v > 0 ? (v < 1 ? v : 1) : 0;
41	}
42	
43	function attach(glider: THREE.Group, e: PlEntry, s: PlSource): void {
44	  e.rig = new PlRig(s, e.seed);
45	  glider.add(e.rig.group);
46	  (glider.children[0] as THREE.Mesh).geometry = exGliderGeometry('canopy');
47	  e.track.has = false;
48	}
49	
50	export function plPreload(): void { if (!OFF) need(); }
51	
52	export function plUpdate(glider: THREE.Group, s: GliderState, dt: number, turnInput?: number): void {
53	  if (OFF) return;
54	  let e = entries.get(glider);
55	  if (!e) {
56	    if (glider.userData.plOff) return;
57	    e = { rig: null, track: { x: 0, y: 0, z: 0, speed: 0, has: false }, sig: { turn: 0, acc: 0, vy: 0, wind: 0 }, seed: ++seeds };
58	    entries.set(glider, e);
59	  }
60	  if (!e.rig) {
61	    const so = need();
62	    if (!so || !glider.visible) return;
63	    attach(glider, e, so);
64	  }
65	  plSignals(e.sig, e.track, s.pos.x, s.pos.y, s.pos.z, s.bank, dt, plWind(), turnInput);
66	  e.rig!.update(e.sig, dt);
67	}
68	
69	/* Dù nhảy vị trí / đổi chủ: lò xo về nghỉ, quên mẫu vị trí (không sinh gia tốc giả) */
70	export function plReset(glider: THREE.Group): void {
71	  const e = entries.get(glider);
72	  if (!e) return;
73	  e.track.has = false; e.track.hasSpeed = false; e.track.acc = 0; e.track.vy = 0;
74	  if (e.rig) e.rig.reset();
75	}
76	
77	/* Gỡ nhân vật: trả hình 'full', dispose rig */
78	export function plDetach(glider: THREE.Group): void {
79	  const e = entries.get(glider);
80	  if (!e) return;
81	  if (e.rig) { e.rig.dispose(); e.rig = null; (glider.children[0] as THREE.Mesh).geometry = exGliderGeometry('full'); }
82	  entries.delete(glider);
83	}
84	
85	export function plSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { plSetWarmLoad(fn); }
86	
87	const ZERO: PlPose = { swingRoll: 0, swingPitch: 0, swingYaw: 0, spineRoll: 0, spinePitch: 0, spineTwist: 0, headYaw: 0, headRoll: 0, legSide: 0, legFore: 0, kneeL: 0, kneeR: 0, legSplit: 0, brakeL: 0, brakeR: 0, packRoll: 0, packPitch: 0, strap: 0 };
88	
89	/* Cho test: real = đang hiện bằng nhân vật có xương; handErr m (điểm nắm ↔ quai phanh, −1 khi chưa có rig); pose bản sao; calls = số lưới đang hiện của dù (mỗi lưới một lệnh vẽ) */
90	export function plDebug(glider: THREE.Group): { real: boolean; handErr: [number, number]; pose: PlPose; calls: number } | null {
91	  const e = entries.get(glider);
92	  let calls = 0;
93	  glider.traverseVisible((o) => { if ((o as THREE.Mesh).isMesh) calls++; });
94	  if (!e) return null;
95	  const r = e.rig;
96	  return { real: !!r && glider.visible, handErr: r ? r.handErr() : [-1, -1], pose: { ...(r ? r.react.pose : ZERO) }, calls };
97	}
98	
99	/* Chỉ dùng trong unit test: thay bộ nạp (null = plLoad thật), quên nguồn và mọi dù đã gắn */
100	export function __plSetLoader(fn: (() => Promise<PlSource | null>) | null): void {
101	  loader = fn || plLoad; gen++;
102	  src = undefined; asked = false;
103	  for (const g of [...entries.keys()]) plDetach(g);
104	}
105

