152	  b.blob(rc, rot(st.tilt), rv.h, E, 5, 10, bone.pel, pack);
153	  /* quai kéo dù dự phòng: tay nắm đỏ ở mép phải hộp, dải đỏ nối vào hộp */
154	  const hp = V(rc.x + rv.handle[0], rc.y, rv.handle[1]);
155	  b.band([V(rc.x - rv.h[0] * 0.3, rc.y + rv.h[1] * 0.5, rv.h[2] + 0.004), V(hp.x - 0.02, hp.y, rv.h[2] + 0.006), hp], [Z, Z, Z], [bone.pel, bone.pel, bone.pel], 0.025, 0.008, red);
