1	/* ===== Người treo dù: nạp mô hình nhân vật có xương (public/people/pilot.glb) (src/explore/pilot/load.ts) =====
2	   - plLoad(): import() động GLTFLoader + SkeletonUtils (chunk riêng, trang thường không tải; cùng chunk với Đi dạo), nạp pilot.glb một lần trong phiên.
3	     Lỗi bất kỳ (mạng, tệp hỏng, thiếu đoạn `sit`, thiếu xương bắt buộc) hoặc quá CONFIG.explore.pilot.loadMs → console.warn một lần, trả null,
4	     không thử lại; promise không bao giờ bị từ chối. Về muộn sau khi đã quá giờ thì bỏ (giữ hình khối suốt phiên, spec §7).
5	   - plSource(): chuẩn hóa cảnh đã nạp: lớp 1 (không vào phản chiếu nước), không đổ / nhận bóng, tắt frustumCulled (hộp bao theo tư thế gốc sai khi diễn).
6	     KHÁC Đi dạo: giữ normalMap và roughnessMap (kênh G của ORM) của glb, không ghi đè độ nhám bằng hằng số.
7	   - Làm nóng shader (D-018): sau khi nạp, chờ hàm do plSetWarm gắn (compileAsync theo cảnh chính, ≤ pilot.warmMs) rồi mới trả nguồn. Thiết kế: spec §4, §7. */
8	import * as THREE from 'three';
9	import { CONFIG } from '../../config';
10	import { plBonesMissing } from './bones';
11	
12	export interface PlSource {
13	  scene: THREE.Object3D;                          // cảnh gốc (không thêm vào scene; chỉ để sao chép)
14	  clip: THREE.AnimationClip;                      // đoạn `sit` (tư thế nền có nhịp thở)
15	  clone: (o: THREE.Object3D) => THREE.Object3D;   // SkeletonUtils.clone (test truyền bản giả)
16	}
17	
18	/* Chuẩn hóa cảnh + đoạn đã nạp thành nguồn dùng chung. Thiếu `sit` hoặc thiếu xương bắt buộc thì ném (plLoad bắt, trả null) */
19	export function plSource(scene: THREE.Object3D, clips: THREE.AnimationClip[], clone: (o: THREE.Object3D) => THREE.Object3D): PlSource {
20	  const clip = clips.find((c) => c.name === 'sit');
21	  if (!clip) throw new Error('thiếu đoạn sit');
22	  const miss = plBonesMissing(scene);
23	  if (miss.length) throw new Error('thiếu xương ' + miss.join(', '));
24	  scene.traverse((o) => {
25	    o.layers.set(1);
26	    const m = o as THREE.Mesh;
27	    if (!m.isMesh) return;
28	    m.castShadow = false; m.receiveShadow = false; m.frustumCulled = false;
29	    const mats = Array.isArray(m.material) ? m.material : [m.material];
30	    for (const mat of mats) if (mat.alphaTest > 0) mat.transparent = false;   // mảnh alpha (nếu có): cắt theo alphaTest, không trộn trong suốt
31	  });
32	  return { scene, clip, clone };
33	}
34	
35	/* Làm nóng shader: explore/index.ts gắn hàm biên dịch sẵn (load.ts không import renderer để chạy được trong unit test) */
36	let warm: ((o: THREE.Object3D) => Promise<unknown>) | null = null;
37	export function plSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { warm = fn; }
38	async function plWarm(o: THREE.Object3D): Promise<void> {
39	  if (!warm) return;
40	  let timer = 0;
41	  try { await Promise.race([warm(o), new Promise<void>((r) => { timer = setTimeout(r, CONFIG.explore.pilot.warmMs) as unknown as number; })]); }
42	  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch như cũ */ }
43	  finally { clearTimeout(timer); }
44	}
45	
46	let cache: Promise<PlSource | null> | null = null;
47	
48	/* Nạp một lần (nhớ đệm). Không bao giờ ném / từ chối: lỗi hoặc quá giờ → warn một lần, null */
49	export function plLoad(): Promise<PlSource | null> {
50	  if (cache) return cache;
51	  const P = CONFIG.explore.pilot;
52	  const work = (async (): Promise<PlSource | null> => {
53	    const [{ GLTFLoader }, SU] = await Promise.all([import('three/addons/loaders/GLTFLoader.js'), import('three/addons/utils/SkeletonUtils.js')]);
54	    const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + P.model);
55	    const src = plSource(gltf.scene, gltf.animations, SU.clone);
56	    await plWarm(src.scene);   // nguồn chỉ "sẵn sàng" sau khi shader skinning đã biên dịch: lần hiện đầu không khựng
57	    return src;
58	  })();
59	  let timer = 0;
60	  const late = new Promise<'late'>((r) => { timer = setTimeout(() => r('late'), P.loadMs) as unknown as number; });
61	  cache = Promise.race([work, late]).then((r) => {
62	    clearTimeout(timer);
63	    if (r === 'late') { console.warn('Dù lượn: tải người treo quá giờ, dùng hình khối'); return null; }
64	    return r;
65	  }, (e) => { clearTimeout(timer); console.warn('Dù lượn: không nạp được người treo, dùng hình khối', e); return null; });
66	  work.catch(() => { /* đã quá giờ: lỗi về muộn không còn ai nghe */ });
67	  return cache;
68	}
