1	/* ===== Người treo dù: trang bị + hình học cánh (src/explore/pilot/gear.ts, src/explore/glider.ts) ===== */
2	import { test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import * as THREE from 'three';
