8	
9	const P = CONFIG.explore.pilot, GL = CONFIG.explore.glider;
10	const BONE = (n: typeof PL_GEAR_BONES[number]) => PL_GEAR_BONES.indexOf(n);
11	const hy = exHangY;
12	/* Vị trí nghỉ mẫu theo cùng quy ước với nhân vật thật: hông thấp hơn điểm móc hang.up, lùi hang.fore; tay ở quai phanh thả */
13	const rest: PlGearRest = {
14	  hang: [0, hy, 0],
15	  pelvis: [-P.hang.fore, hy - P.hang.up, 0],
16	  spine: [-P.hang.fore - 0.04, hy - P.hang.up + 0.2, 0],
17	  handL: [P.toggle.fore, hy + P.toggle.up, -P.toggle.half],
18	  handR: [P.toggle.fore, hy + P.toggle.up, P.toggle.half],
19	  thighL: [-P.hang.fore, hy - P.hang.up, -0.1],
20	  thighR: [-P.hang.fore, hy - P.hang.up, 0.1]
21	};
22	const tris = (g: THREE.BufferGeometry) => (g.index ? g.index.count : g.getAttribute('position').count) / 3;
23	const bbox = (g: THREE.BufferGeometry) => { g.computeBoundingBox(); return g.boundingBox!; };
24	
25	test('hình học trang bị: trần tam giác, thuộc tính, trọng số, không NaN', () => {
26	  const g = plGearGeometry(rest), n = g.getAttribute('position').count;
27	  assert.ok(tris(g) <= 6000, `tam giác ${tris(g)}`);
28	  assert.ok(tris(g) > 200);
29	  for (const k of ['position', 'normal', 'color', 'skinIndex', 'skinWeight']) assert.ok(g.getAttribute(k), k);
30	  const si = g.getAttribute('skinIndex'), sw = g.getAttribute('skinWeight');
31	  for (const name of ['position', 'normal', 'color']) for (const v of g.getAttribute(name).array) assert.ok(Number.isFinite(v), `NaN ở ${name}`);
32	  for (let i = 0; i < n; i++) {
33	    const idx = si.getX(i);
34	    assert.ok(Number.isInteger(idx) && idx >= 0 && idx < PL_GEAR_BONES.length, `skinIndex ${idx}`);
35	    const s = sw.getX(i) + sw.getY(i) + sw.getZ(i) + sw.getW(i);
36	    assert.ok(Math.abs(s - 1) < 1e-6, `tổng trọng số ${s}`);
37	  }
38	});
39	
40	test('gắn xương: wing, hang, handL, handR, pack đều có đỉnh; dây hai đầu hai xương', () => {
41	  const g = plGearGeometry(rest), si = g.getAttribute('skinIndex'), n = g.getAttribute('position').count;
42	  const cnt = new Array(PL_GEAR_BONES.length).fill(0);
