12	/* Cây xương ngồi (m, hệ +X trước mặt, +Y lên, +Z phải): vị trí cục bộ so với cha */
13	function fakeScene(): THREE.Group {
14	  const scene = new THREE.Group(), bip = new THREE.Object3D(); bip.name = 'Bip01'; scene.add(bip);
15	  const bones: THREE.Bone[] = [];
16	  const mk = (name: string, parent: THREE.Object3D, x: number, y: number, z: number): THREE.Bone => { const b = new THREE.Bone(); b.name = 'Bip01_' + name; b.position.set(x, y, z); parent.add(b); bones.push(b); return b; };
17	  const pel = mk('Pelvis', bip, 0, 0, 0), sp = mk('Spine', pel, 0, 0.1, 0), sp1 = mk('Spine1', sp, 0, 0.12, 0), sp2 = mk('Spine2', sp1, 0, 0.14, 0);
