44	  for (const b of ['wing', 'hang', 'handL', 'handR', 'pelvis', 'spine', 'pack', 'thighL', 'thighR'] as const) assert.ok(cnt[BONE(b)] > 0, `không có đỉnh ${b}`);
45	  /* từng dây treo: có đỉnh cả ở hang lẫn wing; từng dây phanh chính: có đỉnh ở một xương tay lẫn wing */
46	  const spans = g.userData.spans as PlGearSpan[];
